using System.Numerics;

using BinaryVibrance.Kaldra.Assets;
using BinaryVibrance.Kaldra.Core.Animation;

namespace BinaryVibrance.Kaldra.Tests;

/// <summary>
/// The glTF loader's rig + animation path, against the committed <c>rigged_bar.glb</c> (a deterministic
/// 2-bone bar with a "bend" rotation clip, generated by the sandbox's rig generator). Asserts the skeleton, the
/// per-vertex skinning data, and the clip read through <see cref="GltfLoader"/> into the neutral Core types.
/// </summary>
public class GltfSkinningLoadTests
{
	private static LoadedModel Load() =>
		GltfLoader.Load(Path.Combine(AppContext.BaseDirectory, "rigged_bar.glb"));

	[Test]
	public void Skeleton_has_two_joints_with_a_single_root_and_one_child()
	{
		var model = Load();

		model.Skeleton.ShouldNotBeNull();
		var skel = model.Skeleton!;
		skel.JointCount.ShouldBe(2);
		skel.InverseBindMatrices.Length.ShouldBe(2);
		skel.LocalBindTransforms.Length.ShouldBe(2);
		// bone0 is a root (-1); bone1's parent is bone0 (index 0). Exactly one root.
		skel.ParentIndices.Count(p => p < 0).ShouldBe(1);
		skel.ParentIndices[1].ShouldBe(0);
	}

	[Test]
	public void Every_primitive_is_skinned_with_normalized_weights_and_in_range_joints()
	{
		var model = Load();
		var skel = model.Skeleton!;

		model.Primitives.ShouldNotBeEmpty();
		foreach (var prim in model.Primitives)
		{
			prim.IsSkinned.ShouldBeTrue();
			prim.SkinnedVertices!.Length.ShouldBe(prim.Vertices.Length);
			foreach (var v in prim.SkinnedVertices!)
			{
				var sum = v.Weights.X + v.Weights.Y + v.Weights.Z + v.Weights.W;
				sum.ShouldBe(1f, 1e-4f); // renormalized
				foreach (var joint in (uint[])[v.Joint0, v.Joint1, v.Joint2, v.Joint3])
					joint.ShouldBeLessThan((uint)skel.JointCount);
			}
		}
	}

	[Test]
	public void The_bend_clip_loads_with_a_rotation_track_on_the_child_joint()
	{
		var model = Load();

		model.Clips.Count.ShouldBe(1);
		var clip = model.Clips[0];
		clip.Name.ShouldBe("bend");
		clip.Duration.ShouldBe(2f, 1e-3f); // last keyframe at t=2
										   // The clip drives joint 1 (bone1) with a rotation track; bone0 is unkeyed.
		var channel = clip.Channels.Single(c => c.JointIndex == 1);
		channel.Rotation.ShouldNotBeNull();
		channel.Rotation!.Times.Length.ShouldBe(3); // keys at 0, 1, 2
		channel.Rotation.Interpolation.ShouldBe(AnimationInterpolation.Linear);
	}

	[Test]
	public void Bind_pose_and_skinned_geometry_share_the_same_positions()
	{
		var model = Load();
		var prim = model.Primitives[0];

		// SkinnedVertices interleaves the same bind-pose geometry as Vertices (plus joints/weights).
		for (var i = 0; i < prim.Vertices.Length; i++)
			Vector3.Distance(prim.Vertices[i].Position, prim.SkinnedVertices![i].Position).ShouldBeLessThan(1e-6f);
	}
}
